// Phase 15: the CPU side of the 8x8 pixel font.
//
// assets/textures/font.png (generated by tools/generate_font.py) is a
// 128x256 atlas of 16px cells indexed by ASCII code: cell (c % 8, c / 8).
// Each 8x8 glyph sits at a 4px offset inside its cell. Unknown / non-ASCII
// characters render as the '?' glyph.
//
// UV convention (shared with the rest of the codebase — textures upload
// without flipping, so v = 0 is the image's TOP row): a glyph's v0 is its
// top edge (smaller v), v1 its bottom edge (larger v).
#pragma once

#include <string>
#include <vector>

#include "core/math/vec2.hpp"
#include "core/math/vec3.hpp"
#include "renderer/mesh.hpp"

namespace mc {

inline constexpr int kFontAtlasWidth = 128;
inline constexpr int kFontAtlasHeight = 256;
inline constexpr int kFontCell = 16;
inline constexpr int kGlyphSize = 8;
inline constexpr int kGlyphOffset = (kFontCell - kGlyphSize) / 2; // 4

struct GlyphUv {
    float u0 = 0.0f, v0 = 0.0f, u1 = 0.0f, v1 = 0.0f; // v0 = glyph top
};

// The 8x8 glyph rect for `c` (ASCII; anything else maps to '?').
GlyphUv glyphUv(char c);

// On-screen advance width of the whole string at `scale` (>= 1): each
// character occupies kGlyphSize*scale plus scale pixels of spacing.
int textWidth(const std::string& text, int scale = 1);

// Appends non-indexed triangle vertices for `text` laid out from the
// top-left corner (x, y) in SCREEN pixels (y grows downward). The glyph
// ink is white in the atlas; the fragment shader modulates it by u_color,
// so the caller picks the text color (and alpha) at draw time.
void makeTextVertices(const std::string& text, int x, int y, int scale,
                      std::vector<MeshVertex>& out);

} // namespace mc
